/// <summary>
/// designed by AVANADE
/// </summary>
[ExtensionOf(classStr(SalesQuotationEditLinesForm))]
final class AVASalesQuotationEditLinesForm_Extension
{
    private KCS_SendMode        sendMode;
    private KCS_PrintWeights    printWeights;
    private RefRecId            custQuotationJourRecId;

}

