/// <summary>
/// N.Freidenberger 24.07.2024
/// </summary>
/// <param name = "_sendMode">_sendMode</param>
/// <returns>KCS_SendMode</returns>
public KCS_SendMode parmSendMode(KCS_SendMode _sendMode = sendMode)
{
    sendMode = _sendMode;
    return sendMode;
}

/// <summary>
/// N.Freidenberger 24.07.2024
/// </summary>
/// <param name = "_printWeights">_printWeights</param>
/// <returns>KCS_PrintWeights</returns>
public KCS_PrintWeights parmPrintWeights(KCS_PrintWeights _printWeights = printWeights)
{
    printWeights = _printWeights;
    return printWeights;
}

/// <summary>
/// N.Freidenberger 24.07.2024
/// </summary>
/// <param name = "_custQuotationJourRecId">_custQuotationJourRecId</param>
/// <returns>RefRecId</returns>
public RefRecId parmCustQuotationJourRecId(RefRecId _custQuotationJourRecId = custQuotationJourRecId)
{
    custQuotationJourRecId = _custQuotationJourRecId;
    return custQuotationJourRecId;
}

/// <summary>
/// Initializes the provided <c>SalesQuotationTable</c> by the document status.
/// </summary>
/// <param name = "_salesQuotationTable">A <c>SalesQuotationTable</c>.</param>
protected void initializeSalesQuotationTableFromDocumentStatus(SalesQuotationTable _salesQuotationTable)
{
    SalesQuotationStatus avaQuotationStatus = _salesQuotationTable.QuotationStatus;

    next initializeSalesQuotationTableFromDocumentStatus(_salesQuotationTable);

    switch (this.documentStatus())
    {
        case DocumentStatus::Quotation:
            if(this.parmSendMode() == KCS_SendMode::Proforma
                || (avaQuotationStatus != SalesQuotationStatus::Created
                    && avaQuotationStatus != SalesQuotationStatus::Sent))
            {
                _salesQuotationTable.QuotationStatus = avaQuotationStatus;
            }

            break;
    }
}

/// <summary>
/// N.Freidenberger 24.07.2024
/// </summary>
/// <param name = "args">args</param>
public static void  main(Args  args)
{
    next main(args);

    Common record = args.record();
    FormDataSource salesQuotationTable_ds;
    SalesQuotationTable     salesQuotationTable;
    if (record && record.TableId == tableNum(SalesQuotationTable))
    {
        salesQuotationTable_ds  = FormDataUtil::getFormDataSource(record);
        salesQuotationTable = record;
    }

    if (salesQuotationTable_ds)
    {
        salesQuotationTable_ds.query().dataSourceTable(tableNum(SalesQuotationTable)).addRange(fieldNum(SalesQuotationTable,QuotationId)).value(salesQuotationTable.QuotationId);
        salesQuotationTable_ds.executeQuery();
    }
}

/// <summary>
/// N.Freidenberger     24.07.2024
/// </summary>
/// <param name = "_documentStatus">_documentStatus</param>
/// <param name = "_parm">_parm</param>
/// <param name = "_getParmId">_getParmId</param>
/// <returns>SalesQuotationEditLinesForm</returns>
static SalesQuotationEditLinesForm construct(DocumentStatus     _documentStatus,
                                                    str                _parm,
                                                    boolean            _getParmId)
{
    SalesQuotationEditLinesForm                 instance =    next construct(_documentStatus,_parm,_getParmId);
    ModuleAxapta moduleAxapta = SalesQuotationEditLinesForm::getCallerModuleFromParm(_parm);

    if (moduleAxapta == ModuleAxapta::SalesOrder && AVASalesParameters::find().SalesQuotQuickPost)
    {
        instance   =  new AVASalesQuotationEditLinesForm_QuickPost(_getParmId);
    }            
    if(!instance)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return instance;
}
